const COMMANDS: &[&str] = &["add_subscription", "refresh_show", "refresh_all", "list_shows", "list_episodes", "recent_episodes", "get_episode", "remove_show", "set_progress", "set_watched", "mark_show_watched", "search_podcasts", "search_show", "load_transcript", "fetch_official_transcript", "transcribe", "cancel_job", "asr_models", "download_model", "delete_model", "get_blob", "set_blob", "get_settings", "set_settings", "set_api_key", "has_api_key", "llm_chat", "translate_texts", "shared_transcript", "shared_exists", "shared_guide", "share_guide", "asr_elsewhere", "log_listen", "listening_stats", "rescan_models", "youtube_subscriptions", "open_privacy_settings", "export_opml", "local_agents", "probe_agent", "agent_models", "warm_agent", "share_translation", "ui_ready", "ui_check", "refresh_config", "youtube_stream", "prepare_youtube", "youtube_sign_in", "youtube_signed_in", "youtube_sign_out", "network_check", "youtube_tracks", "use_youtube_track", "youtube_channel_feed", "qiaomu_detail", "preview_show", "list_models", "tts_speak", "tts_synthesize", "tts_system_voices", "clear_tts_cache", "local_tts_status", "local_tts_install", "local_tts_delete", "cached_show", "save_image", "learn_clip", "save_text", "export_anki", "set_menu_labels", "download_episode", "list_downloads", "delete_download", "clear_downloads", "align_audio", "save_time_map", "list_audio_cache", "audio_stream", "clear_audio_cache", "storage_info", "open_data_folder", "reveal_download", "clear_temp", "full_notes", "app_update_check", "app_update_download", "app_update_install", "shadow_start", "shadow_stop", "shadow_clear", "shadow_ready", "shadow_hear", "open_mic_settings", "video_clip_env", "video_clip_warm", "video_clip_prepare", "video_clip_render", "reveal_file", "db_data_version", "cli_status", "cli_install", "mcp_targets", "mcp_connect", "mcp_disconnect"];

fn main() {
    // The WebView proxy (tauri "macos-proxy") calls Network.framework functions that exist from macOS 14 only.
    // Linked weak, the app still starts on older macOS (they resolve to null there, and are never called: see
    // webview_proxy in lib.rs).
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("macos") {
        println!("cargo:rustc-link-arg=-Wl,-weak_framework,Network");
    }
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(tauri_build::AppManifest::new().commands(COMMANDS))).expect("failed to run tauri-build");
}
